contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint sendAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (sendAmount) + (0)); require(sendAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= sendAmount);

        // Observe owner and balance before any interactions
        address ownerBefore = c.Owner(); if (__ESBMC_reverted()) return;
        uint balanceBefore = address(c).balance;

        // Make a payable call to c to possibly change its balance/state. Use multiplicate to move Ether into c or trigger behavior.
        bool mulReverted;
        c.multiplicate{value: sendAmount}(address(this)); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            mulReverted = true;
        } else {
            mulReverted = false;
        }

        // Attempt withdraw and record whether it reverted
        bool withdrawReverted;
        c.withdraw{value: 0}(); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            withdrawReverted = true;
        } else {
            withdrawReverted = false;
        }

        // Observe owner and balance after the withdraw attempt
        address ownerAfter = c.Owner(); if (__ESBMC_reverted()) return;
        uint balanceAfter = address(c).balance;

        // Assert the general rule:
        // - If this contract was not the owner before, withdraw must revert.
        // - If this contract was the owner before and withdraw did not revert, then Owner remains the same and the contract's balance becomes zero.
        assert(
            (address(this) != ownerBefore && withdrawReverted)
            || (address(this) == ownerBefore && (!withdrawReverted && ownerAfter == ownerBefore && balanceAfter == 0))
        );
    }

    receive() external payable {}
}

