pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MultiplicatorX4} from "../src/MultiplicatorX4.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MultiplicatorX4 c;

    function setUp() public {
        c = new MultiplicatorX4();
    }

    function _run(uint256 sendAmount) internal {
        sendAmount = bound(sendAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP + VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= sendAmount);
        address ownerBefore;
        try c.Owner() returns (address __r) { ownerBefore = __r; } catch { return; }
        uint balanceBefore = address(c).balance;
        bool mulReverted;
        try c.multiplicate{value: sendAmount}(address(this)) {
            mulReverted = false;
        } catch {
            mulReverted = true;
        }
        bool withdrawReverted;
        try c.withdraw{value: 0}() {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }
        address ownerAfter;
        try c.Owner() returns (address __r) { ownerAfter = __r; } catch { return; }
        uint balanceAfter = address(c).balance;
        assertTrue((address(this) != ownerBefore && withdrawReverted)
            || (address(this) == ownerBefore && (!withdrawReverted && ownerAfter == ownerBefore && balanceAfter == 0)));
    }

    function testFuzz_run(uint256 sendAmount) public {
        _run(sendAmount);
    }

    receive() external payable {}
}
